mapper.sql:
FROM t_question_bank q
WHERE q.deleted_at IS NULL

    AND q.question_type = #{query.questionType}


    AND q.difficulty = #{query.difficulty}


    AND q.status = #{query.status}


    AND q.job_id = #{query.jobId}


    AND (
        q.question_text ILIKE CONCAT('%', #{query.keyword}, '%')
        OR q.answer_reference ILIKE CONCAT('%', #{query.keyword}, '%')
        OR q.skill_area ILIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND EXISTS (
        SELECT 1
        FROM t_question_tag_relation qtr
        INNER JOIN t_question_tag qt ON qt.id = qtr.tag_id
        WHERE qtr.question_id = q.id
          AND qt.deleted_at IS NULL
          AND qt.tag_name = #{query.tag}
    )

mapper.select:
SELECT


ORDER BY q.created_at DESC, q.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT qtr.question_id, qt.tag_name FROM t_question_tag_relation qtr INNER JOIN t_question_tag qt ON qt.id = qtr.tag_id WHERE qt.deleted_at IS NULL AND qtr.question_id IN
#{questionId}
ORDER BY qtr.question_id ASC, qtr.id ASC
